  '<x1>Matériel : [POLITIQUE DE RÉEMPLOI / RECYCLAGE]</x1>' => '<x1>Crua-earraí: [POLITIQUE DE RÉEMPLOI / RECYCLAGE]</x1>',
  'TRANSPARENCE' => 'TRÉDHEARCACHT',
  'Notre méthode de mesure' => 'Ár modh tomhais',
